
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_mgga_x_ktbm_9_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("mgga_x_ktbm_9", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.995392416409039e+00, -4.896747819210608e+00, -4.758368059301488e+00, -4.566319879735966e+00, -4.303768090047939e+00, -3.952145643634664e+00, -3.493700959218898e+00, -2.914543454472278e+00, -2.208117763471567e+00, -1.423037162608380e+00, -8.076672470179714e-01, -6.041555220923731e-01, -6.265357277758699e-01, -5.306838830469938e-01, -3.507747689012342e-01, -1.808227959313444e-01, -7.589642742301397e-02, -2.488352240310535e-02, -5.341154214207658e-03, -6.014775392486778e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


